<div class="news-admin-header"><div><p class="eyebrow">External integration</p><h1><?= $record ? 'Edit application function' : 'Add application function' ?></h1><p class="admin-lead">Only approved HTTP/HTTPS destinations are accepted. Do not enter passwords or API secrets.</p></div><a class="button button-secondary" href="<?= e(url('admin/applications')) ?>">Back to functions</a></div>
<form class="panel form-grid application-function-form" method="post" action="<?= e($record ? url('admin/applications/functions/' . $record['id']) : url('admin/applications/functions')) ?>">
    <?= csrf_field() ?>
    <label>Name <input type="text" name="name" value="<?= e(old('name', $record['name'] ?? '')) ?>" required maxlength="150"><?php if ($err = field_error('name')): ?><small class="error"><?= e($err) ?></small><?php endif; ?></label>
    <label>Application type <input type="text" name="application_type" value="<?= e(old('application_type', $record['application_type'] ?? 'External application')) ?>" maxlength="80"></label>
    <label>Category <input type="text" name="category" value="<?= e(old('category', $record['category'] ?? 'Admissions')) ?>" maxlength="80"></label>
    <label>Bootstrap icon class <input type="text" name="icon" value="<?= e(old('icon', $record['icon'] ?? 'bi-box-arrow-up-right')) ?>" placeholder="bi-box-arrow-up-right"><?php if ($err = field_error('icon')): ?><small class="error"><?= e($err) ?></small><?php endif; ?></label>
    <label class="full">Description <textarea name="description" rows="5"><?= e(old('description', $record['description'] ?? '')) ?></textarea></label>
    <label class="full">External website URL <input type="url" name="external_url" value="<?= e(old('external_url', $record['external_url'] ?? '')) ?>" placeholder="https://official.example/apply" maxlength="500"><?php if ($err = field_error('external_url')): ?><small class="error"><?= e($err) ?></small><?php endif; ?><small>Leave blank while configuring a draft. The URL must be supplied by the official external service.</small></label>
    <label>Order number <input type="number" name="sort_order" min="0" max="999999" value="<?= (int) old('sort_order', $record['sort_order'] ?? 0) ?>"></label>
    <label>Publication status <select name="publication_status"><option value="draft" <?= old('publication_status', $record['publication_status'] ?? 'draft') === 'draft' ? 'selected' : '' ?>>Draft</option><option value="published" <?= old('publication_status', $record['publication_status'] ?? '') === 'published' ? 'selected' : '' ?>>Published</option></select></label>
    <label>Active status <select name="status"><option value="active" <?= old('status', $record['status'] ?? '') === 'active' ? 'selected' : '' ?>>Active</option><option value="inactive" <?= old('status', $record['status'] ?? 'inactive') === 'inactive' ? 'selected' : '' ?>>Inactive</option></select></label>
    <label class="checkbox-label"><input type="checkbox" name="open_new_tab" value="1" <?= old('open_new_tab', $record['open_new_tab'] ?? 1) ? 'checked' : '' ?>> Open external website in a new tab</label>
    <div class="form-actions full"><button class="button" type="submit">Save function</button><a class="button button-secondary" href="<?= e(url('admin/applications')) ?>">Cancel</a></div>
</form>
